function readSavedRecord(value:unknown):Record<string,unknown>{if(typeof value!=="string")return{};try{return JSON.parse(value) as Record<string,unknown>}catch{return{}}}
function airedSocialEvents(p:Props,throughDay:number):string[]{const out=new Set<string>();for(let episode=1;episode<=throughDay;episode++){const row=readSavedRecord(p.gameUi?.[episode===1?"day1":`episode${episode}`]);const phase=String(row.phase??row.step??"");const published=episode===1?["social","complete"].includes(phase):episode<=3?["social","complete"].includes(phase):["social","complete","finale"].includes(phase);if(!published)continue;const clips=episode===1?(Array.isArray(row.selectedClips)?row.selectedClips.filter((id)=>row.eventStatus&&typeof row.eventStatus==="object"&&(row.eventStatus as Record<string,{aired?:boolean}>)[String(id)]?.aired):[]):Array.isArray(row.airedClips)?row.airedClips:Array.isArray(row.clips)?row.clips:[];for(const eventId of eventsForAiredClips(episode,clips.map(String)))out.add(eventId);}return [...out];}
function corpusAsItem(item:CorpusItem,comments:string[],_day:number,edit:string):Item{const sender=corpusPersonaLabel(item);const likes=17+item.id.split("").reduce((n,c)=>n+c.charCodeAt(0),0)%583;return{id:item.id,title:corpusItemTitle(item),body:item.text,richText:"",meta:{platform:item.platform,edit,eventId:item.eventId,cpIds:item.cpIds.join("|"),authorRole:item.authorRole,stance:item.stance,xKnowledge:item.xKnowledge},time:`播出后 · ${item.episode}`,sender,avatar:"",kind:"post",media:"",hidden:false,unlock:"",password:"",folder:`D${item.episode.slice(2)}`,favorite:false,outgoing:false,read:false,likes,comments};}
